using UnityEngine;

namespace Copperpine.Arcade {
  public class PlayerController : MonoBehaviour {
    [SerializeField] float speed = 6.5f;
    void Update(){ var h=Input.GetAxisRaw("Horizontal"); transform.Translate(Vector3.right*h*speed*Time.deltaTime); }
  }
}

using UnityEngine;

namespace Copperpine.Arcade {
  public class CameraFollow2D : MonoBehaviour {
    [SerializeField] Transform target; [SerializeField] Vector3 offset = new(0,2,-10);
    void LateUpdate(){ if(!target) return; transform.position = target.position + offset; }
  }
}

using UnityEngine;

namespace Copperpine.Arcade.Combat {
  public class Health : MonoBehaviour {
    public int max=100; public int current;
    void Awake(){ current=max; }
    public void Damage(int amount){ current=Mathf.Max(0,current-amount); }
  }
}

namespace Northway.Tools {
  public static class BuildVersion {
    public const string SemVer = "1.6.13";
    public const int Build = 4827;
  }
}

namespace Northway.Services {
  public static class RemoteConfigKeys {
    public const string FeaturePaywall = "feature_paywall_v2";
