using UnityEngine;

namespace Lumenvale.Audio {
  [CreateAssetMenu(menuName="Audio/Audio Bus")]
  public class AudioBus : ScriptableObject {
    [Range(0f,1f)] public float volume = 1f;
    public bool muted;
  }
}

using UnityEngine;

namespace Lumenvale.Audio {
  public class MusicZone : MonoBehaviour {
    [SerializeField] AudioClip clip; [SerializeField] float fade=0.6f;
    void OnTriggerEnter(Collider other){ if(other.CompareTag("Player")) AudioManager.Instance?.PlayMusic(clip,fade); }
  }
}

using UnityEngine;

namespace Lumenvale.Audio {
  public class AudioManager : MonoBehaviour {
    public static AudioManager Instance {get; private set;}
    [SerializeField] AudioSource music;
    void Awake(){ if(Instance&&Instance!=this){Destroy(gameObject);return;} Instance=this; DontDestroyOnLoad(gameObject); }
    public void PlayMusic(AudioClip clip,float fade){ if(!music) return; music.clip=clip; if(!music.isPlaying) music.Play(); }
  }
}

using UnityEngine;

namespace Harborlight.RPG.Items {
  [CreateAssetMenu(menuName="RPG/Item")]
  public class InventoryItem : ScriptableObject {
    public string itemId; public string displayName;
    public Sprite icon; public int maxStack=99;
  }
}

using System.Collections.Generic;
using UnityEngine;

namespace Harborlight.RPG.Items {
  public class InventorySystem : MonoBehaviour {
    readonly Dictionary<string,int> stacks = new();
    public void Add(string itemId,int count){ stacks[itemId]=stacks.TryGetValue(itemId,out var c)? c+count : count; }
  }
}

using System;

namespace Harborlight.RPG.Persistence {
  [Serializable]
  public class SaveGameV2 {
    public int schema=2; public string playerId; public long savedAtUtc;
  }
}

using System.Net.Http;

namespace KestrelNet.Client {
  public class NetClient {
    readonly HttpClient http = new();
    public HttpClient Http => http;
  }
}

using System;

namespace KestrelNet.Client {
  public static class RetryPolicy {
    public static TimeSpan Backoff(int attempt)=> TimeSpan.FromMilliseconds(250*Math.Pow(2,Math.Min(attempt,6)));
  }
}

using UnityEngine;

namespace Skyrail.World {
  public class SplineRoad : MonoBehaviour {
    [SerializeField] Transform[] points;
    public Vector3 GetPoint(int i)=> points!=null&&i>=0&&i<points.Length? points[i].position: transform.position;
  }
}

using UnityEngine;

namespace Skyrail.World {
  public class TrafficSpawner : MonoBehaviour {
    [SerializeField] GameObject carPrefab; [SerializeField] float interval=2.75f; float t;
    void Update(){ t+=Time.deltaTime; if(t>=interval){ t=0; if(carPrefab) Instantiate(carPrefab,transform.position,transform.rotation); } }
  }
}

using UnityEngine;

namespace Glasswing.UI {
  public class UITabView : MonoBehaviour {
    [SerializeField] GameObject[] panels; int active;
    public void SetActive(int index){ if(panels==null) return; for(int i=0;i<panels.Length;i++) panels[i].SetActive(i==index); active=index; }
  }
}

using UnityEngine;

namespace Glasswing.UI {
  [CreateAssetMenu(menuName="UI/Theme Palette")]
  public class ThemePalette : ScriptableObject {
    public Color primary = new(0.18f,0.52f,0.86f); public Color danger = new(0.86f,0.22f,0.28f);
  }
}

using UnityEditor;

namespace Oxide.EditorTools {
  public static class BakeNavmeshMenu {
    [MenuItem("Tools/Oxide/Bake NavMesh")]
    static void Run(){ UnityEditor.AI.NavMeshBuilder.BuildNavMesh(); }
