using UnityEngine;

namespace Redwood.Core {
  public interface IInteractable {
    void Interact(GameObject interactor);
  }
}

using UnityEngine;
using UnityEngine.UI;

namespace Redwood.UI {
  public class InteractPrompt : MonoBehaviour {
    [SerializeField] CanvasGroup group; [SerializeField] Text label;
    public void Show(string text){ if(label) label.text=text; if(group) group.alpha=1; }
    public void Hide(){ if(group) group.alpha=0; }
  }
}

using UnityEngine;

namespace Seabright.Diagnostics {
  public class CrashReporter : MonoBehaviour {
    void OnEnable(){ Application.logMessageReceived += OnLog; }
    void OnDisable(){ Application.logMessageReceived -= OnLog; }
    void OnLog(string c,string s,LogType t){ if(t==LogType.Exception) Debug.Log("CrashReporter captured exception"); }
  }
}

using System;

namespace Seabright.Net {
  public class RateLimitGuard {
    DateTime until;
    public bool IsLimited => DateTime.UtcNow < until;
    public void BackoffSeconds(int s)=> until = DateTime.UtcNow.AddSeconds(s);
  }
}

using UnityEngine;

namespace Vanta.Platform {
  public class LegacyInputShim {
    public static bool GetJump(){ return Input.GetKey(KeyCode.Space) || Input.GetButton("Jump"); }
  }
}

namespace Vanta.Telemetry {
  public static class AnalyticsEvents {
    public const string SessionStart="session_start";
    public const string Purchase="purchase";
    public const string LevelComplete="level_complete";
  }
}

using System.Collections.Generic;

namespace Fjordline.Core {
  public class ObjectPool<T> where T:new() {
    readonly Stack<T> pool=new();
    public T Get()=> pool.Count>0? pool.Pop(): new T();
    public void Release(T obj)=> pool.Push(obj);
  }
}

using UnityEngine;

namespace Fjordline.Combat {
  public class Projectile : MonoBehaviour {
    [SerializeField] float speed=24f; [SerializeField] float ttl=3.5f;
    void Start(){ Destroy(gameObject,ttl); }
    void Update(){ transform.position += transform.forward*speed*Time.deltaTime; }
  }
}

using UnityEngine;

namespace Fjordline.UI {
  public class DamageNumber : MonoBehaviour {
    [SerializeField] TMPro.TextMeshPro text; float t;
    public void Set(int value){ if(text) text.text=value.ToString(); }
    void Update(){ t+=Time.deltaTime; transform.position += Vector3.up*1.2f*Time.deltaTime; if(t>1.1f) Destroy(gameObject); }
  }
}

using UnityEngine;

namespace Fjordline.Legacy {
  public class DeprecatedSpawner : MonoBehaviour {
    [SerializeField] GameObject prefab;
    void Awake(){ if(prefab) Instantiate(prefab,transform.position,Quaternion.identity); }
  }
}

using UnityEngine;
using UnityEngine.SceneManagement;

namespace Fjordline.Bootstrap {
  public class SceneBootstrapper : MonoBehaviour {
    [SerializeField] string initialScene="Main";
    void Start(){ if(SceneManager.GetActiveScene().name!="Main") SceneManager.LoadScene(initialScene); }
  }
}
